// Android release build (TG-329). android/ is regenerated by `expo prebuild --clean`, so the
// release signing and the Gradle version are set here instead of editing the native project.
const fs = require('fs');
const path = require('path');
const { withAppBuildGradle, withDangerousMod } = require('expo/config-plugins');

// Gradle 9.8.2 is the target required by TG-334. Validate the full Android build in CI.
// Checksum obtained from services.gradle.org.
const GRADLE_VERSION = '9.8.2';
const GRADLE_SHA256 = '21bd5da2de49b642904077f38c0efdc7778e92b3ed0889392dca61b97e389607';

// Gradle reads the keystore and its passwords from the environment at build time: no value is
// ever written into build.gradle. Without ANDROID_KEYSTORE_PATH the release keeps the debug key.
const RELEASE_SIGNING_CONFIG = `
        release {
            if (System.getenv('ANDROID_KEYSTORE_PATH')) {
                storeFile file(System.getenv('ANDROID_KEYSTORE_PATH'))
                storePassword System.getenv('ANDROID_KEYSTORE_PASSWORD')
                keyAlias System.getenv('ANDROID_KEY_ALIAS')
                keyPassword System.getenv('ANDROID_KEY_PASSWORD')
            }
        }`;
const RELEASE_SIGNING = `signingConfig System.getenv('ANDROID_KEYSTORE_PATH') ? signingConfigs.release : signingConfigs.debug`;

const DEBUG_SIGNING_CONFIG = /signingConfigs \{\s*debug \{[^}]*\}/;
const RELEASE_BUILD_TYPE_SIGNING =
  /(buildTypes \{[\s\S]*?release \{[\s\S]*?)signingConfig signingConfigs\.debug/;

/** app/build.gradle with the release signing config. Throws if the template is not the expected one. */
function addReleaseSigning(buildGradle) {
  if (buildGradle.includes(RELEASE_SIGNING)) return buildGradle;
  if (!DEBUG_SIGNING_CONFIG.test(buildGradle) || !RELEASE_BUILD_TYPE_SIGNING.test(buildGradle)) {
    throw new Error('withAndroidRelease: unexpected app/build.gradle, release signing not added');
  }
  return buildGradle
    .replace(RELEASE_BUILD_TYPE_SIGNING, `$1${RELEASE_SIGNING}`)
    .replace(DEBUG_SIGNING_CONFIG, (debug) => debug + RELEASE_SIGNING_CONFIG);
}

/** gradle-wrapper.properties pinned to GRADLE_VERSION and its checksum. */
function pinGradleVersion(properties) {
  const url = `distributionUrl=https\\://services.gradle.org/distributions/gradle-${GRADLE_VERSION}-bin.zip`;
  const lines = properties
    .split(/\r?\n/)
    .filter((line) => line !== '' && !line.startsWith('distributionSha256Sum='))
    .map((line) => (line.startsWith('distributionUrl=') ? url : line));
  return [...lines, `distributionSha256Sum=${GRADLE_SHA256}`, ''].join('\n');
}

function withAndroidRelease(config) {
  config = withAppBuildGradle(config, (mod) => {
    mod.modResults.contents = addReleaseSigning(mod.modResults.contents);
    return mod;
  });
  return withDangerousMod(config, [
    'android',
    (mod) => {
      const file = path.join(
        mod.modRequest.platformProjectRoot,
        'gradle',
        'wrapper',
        'gradle-wrapper.properties',
      );
      fs.writeFileSync(file, pinGradleVersion(fs.readFileSync(file, 'utf8')));
      return mod;
    },
  ]);
}

module.exports = withAndroidRelease;
module.exports.addReleaseSigning = addReleaseSigning;
module.exports.pinGradleVersion = pinGradleVersion;
